#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
	// your code goes here
    int t;cin>>t;
    while(t--){
        ll n;cin>>n;
        ll m = 3*n;
        vector<long long> arr(m);
        for(int i = 0;i<m;i++){
            cin>>arr[i];
        }
        sort(arr.rbegin(),arr.rend());
        vector<long long> pref(m+1);
        for(int i = 0;i<m;i++){
            pref[i+1] = pref[i]+arr[i];
        }
        ll ans = 0;
        for(ll i = 0;i<=n;i++){
            ll r = 0;
            ll e = n-i-1;
            ll ans1 = 0;
            while(r<=e){
                ll mid = (r+e)/2;
                ll dist = arr[i+2*mid]+arr[i+2*mid+1]-3*arr[m-2*i-mid-1];
                if(dist>0){
                    ans1 = mid + 1;
                    r = mid + 1;
                }
                else{
                    e = mid - 1;
                }
            }
            ll k1 = max(0ll,ans1-2);
            ll k2 = min(n-i,ans1+2);
            for(ll j = k1;j<=k2;j++){
                ans = max(ans,2*pref[i]+pref[i+2*j]+3*pref[m-2*i-j]);
            }
        }
        cout<<ans<<"\n";
    }
}
